local function slayer(lvl) return { type = "skill", skill = "slayer", level = lvl } end
local function combat(lvl) return { type = "combat", level = lvl } end
local function skill(name, lvl) return { type = "skill", skill = name, level = lvl } end
local function quest(name) return { type = "quest", quest = name } end
local function quest_started(name) return { type = "quest_started", quest = name,
  label = "Partial completion of " .. name } end
local function manual(id, label, default) return { type = "manual", id = id, label = label,
  default = default } end
local function game_var(vars, id, label, default) return { type = "game_var", vars = vars,
  id = id, label = label, default = default } end

